<h1><?= e(t('Review shared records')) ?></h1><section class="card"><form method="post" action="/platform/objects/apply"><?= csrf_field() ?><?php foreach($preview['rows']as $item): ?><article class="lesson-entry"><h2><?= e($item['record']['title']??$item['record']['name']) ?></h2><p><?= e($item['kind']) ?></p><dl><?php foreach($item['record']as $key=>$value): ?><dt><?= e($key) ?></dt><dd><?= nl2br(e($value)) ?></dd><?php endforeach; ?></dl><?php if($item['conflict']): ?><p><?= e(t('A local edit or deletion differs from this incoming version.')) ?></p><label><?= e(t('Resolution')) ?><select name="choices[<?= e($item['id']) ?>]" required><option value=""><?= e(t('Choose…')) ?></option><option value="local"><?= e(t('Keep local record / deletion')) ?></option><option value="remote"><?= e(t('Accept incoming (preserve prior document as a separate version)')) ?></option></select></label><?php else: ?><p><?= e(t('Ready to merge.')) ?></p><?php endif; ?></article><?php endforeach; ?><button><?= e(t('Confirm reviewed records')) ?></button> <a href="/platform"><?= e(t('Cancel')) ?></a></form></section>
